fn median_of(window: List[Int]) -> Float {
  let s = window.sort()
  let count = s.len()
  let mid = count / 2
  if count % 2 == 1 {
    return s.get_or(mid, 0).to_float()
  }
  let lo = s.get_or(mid - 1, 0).to_float()
  let hi = s.get_or(mid, 0).to_float()
  return (lo + hi) / 2.0
}

pub fn medians(xs: List[Int], k: Int) -> List[Float] {
  let none: List[Float] = []
  if k < 1 or k > xs.len() {
    return none
  }
  let starts = range(0, xs.len() - k + 1)
  return starts.map(fn(i) => median_of(xs.slice(i, i + k)))
}
